package com.rootopathy.careos.administration.application;
import com.rootopathy.careos.administration.domain.OrganizationUnitDirectory; import com.rootopathy.careos.governance.application.GovernedMutationExecutor; import com.rootopathy.careos.governance.domain.*; import com.rootopathy.careos.tenancy.application.TenantAuthorizationOperations; import com.rootopathy.careos.tenancy.domain.*; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.time.*; import java.util.*; import java.util.regex.Pattern; import org.springframework.stereotype.Service; import tools.jackson.databind.ObjectMapper;
@Service public class OrganizationUnitService {
 public static final String LIFECYCLE="network.structure.lifecycle";
 private static final Pattern CODE=Pattern.compile("[A-Z0-9][A-Z0-9_-]{1,31}"),KEY=Pattern.compile("[A-Za-z0-9._:-]{16,128}"),ETAG=Pattern.compile("\"organization-unit:([0-9a-fA-F-]{36}):([0-9]{1,19})\""); private final TenantAuthorizationOperations auth;private final GovernedMutationExecutor mutations;private final OrganizationUnitStore store;private final ObjectMapper mapper;private final Clock clock;
 public OrganizationUnitService(TenantAuthorizationOperations a,GovernedMutationExecutor m,OrganizationUnitStore s,ObjectMapper o,Clock c){auth=a;mutations=m;store=s;mapper=o;clock=c;}
 public OrganizationUnitDirectory directory(Read c){return auth.execute(request(c.organizationId,c.actorId,c.correlationId,FacilityService.READ,null),x->store.directory(x,c.facilityId));}
 public IdempotencyOutcome create(Create c){var reason=text(c.reason,"reason",10,500);validKey(c.idempotencyKey);var draft=draft(c.facilityId,c.parentId,c.unitCode,c.unitType,c.name,c.effectiveFrom,c.effectiveTo);var command=new IdempotencyCommand(FacilityService.MANAGE,c.idempotencyKey,hash(draft,reason),clock.instant().plusSeconds(86400));return mutations.execute(request(c.organizationId,c.actorId,c.correlationId,FacilityService.MANAGE,reason),command,ctx->{var r=store.create(ctx,draft);var payload=payload(r.unitId(),"created",c.parentId,"none","draft",0);return new GovernedMutation(new IdempotentResponse(201,"application/json",json(r.directory())),new GovernanceEvidence(new AuditRecord("network.unit.changed",1,"organization_unit",r.unitId(),reason,payload),new OutboxRecord("network.unit.changed",1,"organization_unit",r.unitId(),payload)));});}
 public IdempotencyOutcome update(Update c){var reason=text(c.reason,"reason",10,500);validKey(c.idempotencyKey);var revision=revision(c.ifMatch,c.unitId);var draft=draft(c.facilityId,c.parentId,c.unitCode,c.unitType,c.name,c.effectiveFrom,c.effectiveTo);var command=new IdempotencyCommand(FacilityService.MANAGE,c.idempotencyKey,hash(c.unitId,revision,draft,reason),clock.instant().plusSeconds(86400));return mutations.execute(request(c.organizationId,c.actorId,c.correlationId,FacilityService.MANAGE,reason),command,ctx->{var r=store.update(ctx,c.unitId,revision,draft);var payload=payload(r.unitId(),"updated",c.parentId,"draft","draft",r.lockVersion());return new GovernedMutation(new IdempotentResponse(200,"application/json",json(r.directory())),new GovernanceEvidence(new AuditRecord("network.unit.changed",1,"organization_unit",r.unitId(),reason,payload),new OutboxRecord("network.unit.changed",1,"organization_unit",r.unitId(),payload)));});}
 public IdempotencyOutcome reparent(Reparent c){var reason=text(c.reason,"reason",10,500);validKey(c.idempotencyKey);var revision=revision(c.ifMatch,c.unitId);var now=clock.instant();if(c.effectiveFrom==null||c.effectiveFrom.isBefore(now.minusSeconds(300))||c.effectiveFrom.isAfter(now.plusSeconds(300)))throw new IllegalArgumentException("effectiveFrom must be current for this immediate reparenting boundary");var command=new IdempotencyCommand(FacilityService.MANAGE,c.idempotencyKey,hash(c.unitId,revision,c.parentId,c.effectiveFrom,reason),now.plusSeconds(86400));return mutations.execute(request(c.organizationId,c.actorId,c.correlationId,FacilityService.MANAGE,reason),command,ctx->{var r=store.reparent(ctx,c.facilityId,c.unitId,revision,c.parentId,c.effectiveFrom);var payload=json(Map.of("recordId",r.unitId(),"previousParentId",r.previousParentId()==null?"":r.previousParentId().toString(),"parentId",r.parentId()==null?"":r.parentId().toString(),"effectiveFrom",r.effectiveFrom().toString(),"lockVersion",r.lockVersion()));return new GovernedMutation(new IdempotentResponse(200,"application/json",json(r.directory())),new GovernanceEvidence(new AuditRecord("network.unit.reparented",1,"organization_unit",r.unitId(),reason,payload),new OutboxRecord("network.unit.reparented",1,"organization_unit",r.unitId(),payload)));});}
 public IdempotencyOutcome activate(Lifecycle c){return lifecycle(c,"draft","active","activated");} public IdempotencyOutcome suspend(Lifecycle c){return lifecycle(c,"active","suspended","suspended");} public IdempotencyOutcome reactivate(Lifecycle c){return lifecycle(c,"suspended","active","reactivated");}
 private IdempotencyOutcome lifecycle(Lifecycle c,String from,String to,String change){var reason=text(c.reason,"reason",10,500);validKey(c.idempotencyKey);var revision=revision(c.ifMatch,c.unitId);var command=new IdempotencyCommand(LIFECYCLE,c.idempotencyKey,hash(c.unitId,revision,to,reason),clock.instant().plusSeconds(86400));return mutations.execute(new TenantAuthorizationRequest(c.organizationId,new AuthenticatedActorContext(c.actorId,"organization-unit-administration",c.correlationId),new OperationKey(LIFECYCLE),reason,c.recentAuthenticationAt,c.mfaAuthenticatedAt,null),command,ctx->{var r=store.transition(ctx,c.facilityId,c.unitId,revision,from,to);var evidence=payload(r.unitId(),change,r.parentId(),from,to,r.lockVersion());return new GovernedMutation(new IdempotentResponse(200,"application/json",json(r.directory())),new GovernanceEvidence(new AuditRecord("network.unit.changed",1,"organization_unit",r.unitId(),reason,evidence),new OutboxRecord("network.unit.changed",1,"organization_unit",r.unitId(),evidence)));});}
 public IdempotencyOutcome close(Close c){var reason=text(c.reason,"reason",10,500);validKey(c.idempotencyKey);var revision=revision(c.ifMatch,c.unitId);var now=clock.instant();if(c.effectiveTo==null||c.effectiveTo.isBefore(now.minusSeconds(300))||c.effectiveTo.isAfter(now.plusSeconds(300)))throw new IllegalArgumentException("effectiveTo must be current for this immediate closure boundary");var command=new IdempotencyCommand(LIFECYCLE,c.idempotencyKey,hash(c.unitId,revision,"closed",c.effectiveTo,reason),now.plusSeconds(86400));return mutations.execute(new TenantAuthorizationRequest(c.organizationId,new AuthenticatedActorContext(c.actorId,"organization-unit-administration",c.correlationId),new OperationKey(LIFECYCLE),reason,c.recentAuthenticationAt,c.mfaAuthenticatedAt,null),command,ctx->{var r=store.close(ctx,c.facilityId,c.unitId,revision,c.effectiveTo);var evidence=payload(r.unitId(),"closed",r.parentId(),r.fromState(),"closed",r.lockVersion());return new GovernedMutation(new IdempotentResponse(200,"application/json",json(r.directory())),new GovernanceEvidence(new AuditRecord("network.unit.changed",1,"organization_unit",r.unitId(),reason,evidence),new OutboxRecord("network.unit.changed",1,"organization_unit",r.unitId(),evidence)));});}
 private static OrganizationUnitStore.Draft draft(UUID facilityId,UUID parentId,String unitCode,String unitType,String name,Instant from,Instant to){var code=text(unitCode,"unitCode",2,32).toUpperCase(Locale.ROOT);if(!CODE.matcher(code).matches())throw new IllegalArgumentException("invalid unitCode");var type=text(unitType,"unitType",2,24);if(!Set.of("department","unit").contains(type))throw new IllegalArgumentException("invalid unitType");if(from==null||to!=null&&!to.isAfter(from))throw new IllegalArgumentException("invalid effective range");return new OrganizationUnitStore.Draft(facilityId,parentId,code,type,text(name,"name",2,120),from,to);}
 private static void validKey(String key){if(key==null||!KEY.matcher(key).matches())throw new IllegalArgumentException("invalid Idempotency-Key");} private static long revision(String etag,UUID id){var m=etag==null?null:ETAG.matcher(etag);if(m==null||!m.matches())throw new OrganizationUnitException(OrganizationUnitException.Reason.PRECONDITION_REQUIRED,"A strong organization-unit If-Match value is required.");if(!UUID.fromString(m.group(1)).equals(id))throw new OrganizationUnitException(OrganizationUnitException.Reason.STALE,"The organization-unit entity tag does not match this resource.");return Long.parseLong(m.group(2));} private String payload(UUID id,String change,UUID parent,String from,String to,long revision){return json(Map.of("recordId",id,"changeType",change,"parentId",parent==null?"":parent.toString(),"fromState",from,"toState",to,"lockVersion",revision));}
 private TenantAuthorizationRequest request(UUID o,UUID a,String c,String op,String reason){return new TenantAuthorizationRequest(o,new AuthenticatedActorContext(a,"organization-unit-administration",c),new OperationKey(op),reason,null,null,null);} private static String text(String v,String f,int min,int max){var n=v==null?"":v.strip();if(n.length()<min||n.length()>max||n.codePoints().anyMatch(Character::isISOControl))throw new IllegalArgumentException("invalid "+f);return n;} private String json(Object v){try{return mapper.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException(e);}} private static String hash(Object...v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Arrays.toString(v).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 public record Read(UUID organizationId,UUID actorId,String correlationId,UUID facilityId){} public record Create(UUID organizationId,UUID actorId,String correlationId,String idempotencyKey,UUID facilityId,UUID parentId,String unitCode,String unitType,String name,Instant effectiveFrom,Instant effectiveTo,String reason){} public record Update(UUID organizationId,UUID actorId,String correlationId,String idempotencyKey,String ifMatch,UUID facilityId,UUID unitId,UUID parentId,String unitCode,String unitType,String name,Instant effectiveFrom,Instant effectiveTo,String reason){} public record Reparent(UUID organizationId,UUID actorId,String correlationId,String idempotencyKey,String ifMatch,UUID facilityId,UUID unitId,UUID parentId,Instant effectiveFrom,String reason){} public record Lifecycle(UUID organizationId,UUID actorId,String correlationId,String idempotencyKey,String ifMatch,UUID facilityId,UUID unitId,String reason,Instant recentAuthenticationAt,Instant mfaAuthenticatedAt){} public record Close(UUID organizationId,UUID actorId,String correlationId,String idempotencyKey,String ifMatch,UUID facilityId,UUID unitId,Instant effectiveTo,String reason,Instant recentAuthenticationAt,Instant mfaAuthenticatedAt){}
}
